def lesson(week, title, summary, outcomes, concepts, headers, rows, example, steps,
           deliverables, questions, answers, safety, diagram, rubric, refs=()):
    return {
        "id": f"week-{week:02d}", "week": week, "kind": "week", "title": title,
        "phase": (week - 1) // 4, "summary": summary, "hours": 6,
        "outcomes": outcomes, "concepts": concepts, "headers": headers, "rows": rows,
        "example": example, "steps": steps, "deliverables": deliverables,
        "questions": questions, "answers": answers, "safety": safety,
        "diagram": diagram, "rubric": rubric, "refs": list(refs),
    }


